#!/usr/bin/env node
'use strict';
/**
 * verify-recurring-issue-date.js — N38 (Rule 10). A recurring invoice/bill generated by the scheduler is
 * issued on its SCHEDULED calendar date, and is recognised (books + ledger) on that date.
 *
 * Defect: the scheduler fires on the ENTITY-local day but stamped no issue_date, so recognition fell back
 * to created_at — a UTC instant. For an entity east of UTC the run fires while UTC is still the previous
 * day, so a run for the 1st landed in the previous month (and on 1 January, the previous fiscal year).
 *
 * Seed (Rule 4 + Rule 10 seed corollary — the instant sits in the inter-zone gap): pinned clock
 * 2026-07-25T16:00Z; entity zone Pacific/Kiritimati (UTC+14) → local date 2026-07-26. Recurring invoice
 * and bill with next_run 2026-07-26 fire now (UTC is still 25 July). Expected:
 *   generated invoice/bill issue_date = 2026-07-26        (bug: none)
 *   ledger entry_date for each        = 2026-07-26        (bug: the created_at date, not the scheduled day)
 *   node -r ./tests/harness/clock.js tests/harness/verify-recurring-issue-date.js
 */

const bcrypt = require('bcryptjs');
require('./clock.js');
const { startScratchPostgres } = require('./pgScratch.js');
const { bootServer } = require('./boot.js');

let pass = 0, fail = 0;
const A = (name, ok, d) => { ok ? (pass++, console.log('  PASS  ' + name)) : (fail++, console.log('  FAIL  ' + name + (d ? '\n          ' + d : ''))); };

async function main() {
  const scratch = await startScratchPostgres({ keep: false });
  const c = scratch.client;
  let server = null;
  try {
    server = await bootServer(scratch.url);
    const srv = require('../../server.js');
    const uid = (await c.query(`INSERT INTO users (user_id,entity_id,data) VALUES (NULL,NULL,$1) RETURNING id`, [{ email: 'recur@finflow.test', plan: 'business', role: 'owner', password: bcrypt.hashSync('x', 10) }])).rows[0].id;
    const eid = (await c.query(`INSERT INTO entities (user_id,entity_id,data) VALUES ($1,NULL,$2) RETURNING id`, [uid, { name: 'Kiribati Co', currency: 'AUD', is_active: 1, timezone: 'Pacific/Kiritimati' }])).rows[0].id;
    await c.query(`INSERT INTO recurring_invoices (user_id,entity_id,data) VALUES ($1,$2,$3)`, [uid, eid, { client: 'Monthly Client', amount: 900, frequency: 'Monthly', next_run: '2026-07-26', status: 'active' }]);
    await c.query(`INSERT INTO recurring_bills (user_id,entity_id,data) VALUES ($1,$2,$3)`, [uid, eid, { vendor: 'Monthly Vendor', amount: 300, frequency: 'Monthly', next_run: '2026-07-26', status: 'active' }]);

    console.log('\n' + '='.repeat(78));
    console.log('  RECURRING DOCUMENTS ISSUED ON THEIR SCHEDULED DATE (UTC+14 entity, UTC still 25 Jul)');
    console.log('='.repeat(78));

    await srv.runRecurringScheduler();
    const inv = (await c.query(`SELECT id, data->>'issue_date' d FROM invoices WHERE user_id=$1`, [uid])).rows;
    const bill = (await c.query(`SELECT id, data->>'issue_date' d FROM bills WHERE user_id=$1`, [uid])).rows;
    A('scheduler fired: 1 invoice and 1 bill generated (entity-local day is 26 Jul)', inv.length === 1 && bill.length === 1, `inv=${inv.length} bill=${bill.length}`);
    A('invoice issue_date = 2026-07-26 (bug: none)', inv[0] && inv[0].d === '2026-07-26', 'issue_date=' + (inv[0] && inv[0].d));
    A('bill issue_date = 2026-07-26 (bug: none)', bill[0] && bill[0].d === '2026-07-26', 'issue_date=' + (bill[0] && bill[0].d));
    const ed = async (type, id) => { const r = (await c.query(`SELECT entry_date::text d FROM ledger_entries WHERE user_id=$1 AND source_type=$2 AND source_id=$3`, [uid, type, id])).rows[0]; return r && r.d; };
    A('invoice recognised in the ledger on 2026-07-26 (bug: the created_at date)', inv[0] && (await ed('invoice', inv[0].id)) === '2026-07-26', 'entry_date=' + (inv[0] && await ed('invoice', inv[0].id)));
    A('bill recognised in the ledger on 2026-07-26 (bug: the created_at date)', bill[0] && (await ed('bill', bill[0].id)) === '2026-07-26', 'entry_date=' + (bill[0] && await ed('bill', bill[0].id)));
    const nr = (await c.query(`SELECT data->>'next_run' n FROM recurring_invoices WHERE user_id=$1`, [uid])).rows[0].n;
    A('control: schedule advanced to 2026-08-26', nr === '2026-08-26', 'next_run=' + nr);
  } finally {
    if (server) { try { await server.close(); } catch (_) {} }
    await scratch.stop();
  }
  console.log('\n' + '-'.repeat(78));
  console.log(fail ? `  ${fail} FAILED — ${pass} passed, ${fail} failed  (recurring issue date)` : `  ALL GREEN — ${pass} passed, 0 failed  (recurring issue date)`);
  console.log('-'.repeat(78));
  process.exit(fail ? 1 : 0);
}
main().catch(e => { console.error('[harness] fatal:', e && e.stack || e); process.exit(2); });
